# Port matching for in-place plugin replacement. Pure Python, no Qt.
# The optional LV2 role catalog is generated by scripts/scrape_lv2_port_roles.py.

import json
import os
import re

MODE_IN = "in"
MODE_OUT = "out"

KIND_AUDIO = "audio"
KIND_MIDI = "midi"
KIND_CV = "cv"
KIND_PARAM = "param"
KIND_OTHER = "other"

_TYPE_TO_KIND = {
    1: KIND_AUDIO,   # PORT_TYPE_AUDIO_JACK
    2: KIND_MIDI,    # PORT_TYPE_MIDI_JACK
    3: KIND_MIDI,    # PORT_TYPE_MIDI_ALSA
    4: KIND_PARAM,   # PORT_TYPE_PARAMETER
}
_MODE_TO_STR = {1: MODE_IN, 2: MODE_OUT}

_SIDE_RE = re.compile(r"side\s*chain|sidechain|\bsc\b|\bkey\b|external|\bext\b", re.I)

_CATALOG = None


def _catalog():
    global _CATALOG
    if _CATALOG is None:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "lv2_port_roles.json")
        try:
            with open(path, encoding="utf-8") as handle:
                _CATALOG = json.load(handle)
        except Exception as exc:
            import sys
            sys.stderr.write("rewire: cannot load %s: %s\n" % (path, exc))
            _CATALOG = {}
    return _CATALOG


def kind_from_type(port_type):
    return _TYPE_TO_KIND.get(port_type, KIND_OTHER)


def mode_from_value(port_mode):
    return _MODE_TO_STR.get(port_mode, MODE_IN)


def normalize_port(port):
    """Accept a normalized dict, a plain dict, or a canvas port object."""
    if isinstance(port, dict):
        if isinstance(port.get("mode"), str) and "kind" in port:
            return dict(port)
        return {
            "key": port.get("port_id", port.get("key")),
            "name": port.get("port_name", port.get("name", "")),
            "mode": mode_from_value(port.get("port_mode", 0)),
            "kind": kind_from_type(port.get("port_type", 0)),
            "index": port.get("index", 0),
            "alternate": bool(port.get("is_alternate", False)),
            "catalog_role": port.get("catalog_role"),
        }
    mode = getattr(port, "mode", None)
    kind = getattr(port, "kind", None)
    if isinstance(mode, str) and kind is not None:
        return {
            "key": getattr(port, "key", None),
            "name": getattr(port, "name", ""),
            "mode": mode,
            "kind": kind,
            "index": getattr(port, "index", 0),
            "alternate": bool(getattr(port, "alternate", False)),
            "catalog_role": getattr(port, "catalog_role", None),
        }
    return {
        "key": getattr(port, "port_id", getattr(port, "key", None)),
        "name": getattr(port, "port_name", getattr(port, "name", "")),
        "mode": mode_from_value(getattr(port, "port_mode", 0)),
        "kind": kind_from_type(getattr(port, "port_type", 0)),
        "index": getattr(port, "index", 0),
        "alternate": bool(getattr(port, "is_alternate", False)),
        "catalog_role": getattr(port, "catalog_role", None),
    }


def attach_catalog_roles(ports, label):
    """Fill port['catalog_role'] from the scraped LV2 catalog, by bucket index."""
    if not label:
        return ports
    roles = _catalog().get(label)
    if not roles:
        return ports
    counters = {}
    for port in ports:
        bucket = port["kind"] + "_" + port["mode"]
        index = counters.get(bucket, 0)
        counters[bucket] = index + 1
        values = roles.get(bucket)
        if values and index < len(values):
            port["catalog_role"] = values[index]
    return ports


def _is_sidechain(name):
    return bool(_SIDE_RE.search(name or ""))


def _channel_from_name(name):
    text = re.sub(r"[_\-.]+", " ", (name or "").lower()).strip()
    if re.search(r"\b(left)\b|\bfl\b|\bfront left\b", text):
        return 0
    if re.search(r"\b(right)\b|\bfr\b|\bfront right\b", text):
        return 1
    if re.search(r"\b(center|centre)\b", text):
        return 2
    if re.search(r"\blfe\b|\bsub\b", text):
        return 3
    if re.search(r"\b(side left|sl)\b", text):
        return 4
    if re.search(r"\b(side right|sr)\b", text):
        return 5
    if re.search(r"(?:^|in|out|input|output)[ _-]?l$", text):
        return 0
    if re.search(r"(?:^|in|out|input|output)[ _-]?r$", text):
        return 1
    match = re.search(r"(?:^|in|out|input|output)[ _-]?(\d+)$", text)
    if match:
        return max(0, int(match.group(1)) - 1)
    return None


def _base_role(port):
    kind = port["kind"]
    if kind == KIND_MIDI:
        return "event"
    if kind == KIND_CV:
        return "cv:%i" % port["index"]
    if kind == KIND_AUDIO:
        side = _is_sidechain(port["name"])
        if port.get("bucket_count") == 1:
            channel = 0
        else:
            channel = _channel_from_name(port["name"])
            if channel is None:
                if side and "side_index" in port:
                    channel = port["side_index"]
                else:
                    channel = port["index"]
        return ("sc:%i" if side else "ch:%i") % channel
    return "%s:%i" % (kind, port["index"])


def port_role(port):
    """Canonical role: 'ch:N', 'sc:N', 'event', 'cv:N' or '<kind>:N'."""
    port = normalize_port(port)
    if port.get("catalog_role"):
        return port["catalog_role"]
    if port.get("computed_role"):
        return port["computed_role"]
    return _base_role(port)


def _assign_roles(ports):
    """Give each port a computed_role; repeated names fall back to position."""
    buckets = {}
    for port in ports:
        buckets.setdefault((port["mode"], port["kind"]), []).append(port)
    for items in buckets.values():
        base = [_base_role(port) for port in items]
        duplicates = len(set(base)) < len(base)
        for port, role in zip(items, base):
            if port.get("catalog_role"):
                continue
            if duplicates and port["kind"] == KIND_AUDIO:
                side = _is_sidechain(port["name"])
                number = port.get("side_index", port["index"]) if side else port["index"]
                role = ("sc:%i" if side else "ch:%i") % number
            port["computed_role"] = role


def index_ports(ports):
    """Normalize and assign per-(mode,kind) indices, bucket sizes and sidechain ordinals."""
    normalized = [normalize_port(port) for port in ports]
    totals = {}
    for port in normalized:
        key = (port["mode"], port["kind"])
        totals[key] = totals.get(key, 0) + 1
    counters = {}
    side_counters = {}
    for port in normalized:
        key = (port["mode"], port["kind"])
        index = counters.get(key, 0)
        counters[key] = index + 1
        port["index"] = index
        port["bucket_count"] = totals[key]
        if port["kind"] == KIND_AUDIO and not port.get("catalog_role") and _is_sidechain(port["name"]):
            side_index = side_counters.get(key, 0)
            side_counters[key] = side_index + 1
            port["side_index"] = side_index
    _assign_roles(normalized)
    return normalized


def _role_label(mode, kind, role):
    direction = "In" if mode == MODE_IN else "Out"
    if role == "event":
        return "Event " + direction
    if role.startswith("sc:"):
        return "Sidechain %s #%i" % (direction, int(role.split(":")[1]) + 1)
    if role.startswith("ch:"):
        return "Audio %s #%i" % (direction, int(role.split(":")[1]) + 1)
    if role.startswith("cv:"):
        return "CV %s #%i" % (direction, int(role.split(":")[1]) + 1)
    return "%s %s" % (kind.title(), direction)


def role_target(port):
    port = normalize_port(port)
    role = port_role(port)
    return {
        "role": (port["mode"], port["kind"], port["index"]),
        "role_key": role,
        "label": _role_label(port["mode"], port["kind"], role),
    }


def actual_target(port):
    port = normalize_port(port)
    return {
        "name": port["name"],
        "mode": port["mode"],
        "kind": port["kind"],
        "index": port["index"],
        "role_key": port_role(port),
        "label": port["name"],
    }


def _compatible(old, new):
    return old["mode"] == new["mode"] and old["kind"] == new["kind"]


def _pick_exact(old, candidates, used):
    for new in candidates:
        if new["key"] in used:
            continue
        if _compatible(old, new) and old["name"].casefold() == new["name"].casefold():
            return new, "name", 1.0
    return None, None, 0.0


def _pick_role(old, candidates, used):
    role = port_role(old)
    for new in candidates:
        if new["key"] in used:
            continue
        if _compatible(old, new) and port_role(new) == role:
            return new, "role", 0.9
    return None, None, 0.0


def _pick_index(old, candidates, used):
    old_side = port_role(old).startswith("sc:")
    for new in candidates:
        if new["key"] in used:
            continue
        if not _compatible(old, new) or new["index"] != old["index"]:
            continue
        if old_side != port_role(new).startswith("sc:"):
            continue
        return new, "channel", 0.8
    return None, None, 0.0


def match_ports(old_ports, new_ports=None):
    """Rows of {old, target, reason, confidence}.

    new_ports=None means the replacement has not been loaded yet: targets are
    role descriptors resolved after the plugin arrives.
    """
    old_ports = index_ports(old_ports)
    if new_ports is None:
        return [
            {
                "old": port,
                "target": role_target(port),
                "reason": "role",
                "confidence": 0.6,
            }
            for port in old_ports
        ]

    new_ports = index_ports(new_ports)
    used = set()
    rows = []
    pending = []

    for old in old_ports:
        new, reason, confidence = _pick_exact(old, new_ports, used)
        if new is not None:
            used.add(new["key"])
            rows.append({"old": old, "target": actual_target(new), "reason": reason, "confidence": confidence})
        else:
            pending.append(old)

    unmatched = []
    for old in pending:
        new, reason, confidence = _pick_role(old, new_ports, used)
        if new is not None:
            used.add(new["key"])
            rows.append({"old": old, "target": actual_target(new), "reason": reason, "confidence": confidence})
        else:
            unmatched.append(old)

    still = []
    for old in unmatched:
        new, reason, confidence = _pick_index(old, new_ports, used)
        if new is not None:
            used.add(new["key"])
            rows.append({"old": old, "target": actual_target(new), "reason": reason, "confidence": confidence})
        else:
            still.append(old)

    for old in still:
        rows.append({"old": old, "target": None, "reason": "none", "confidence": 0.0})

    order = {(MODE_IN, KIND_AUDIO): 0, (MODE_IN, KIND_MIDI): 1, (MODE_IN, KIND_CV): 2,
             (MODE_IN, KIND_PARAM): 3, (MODE_IN, KIND_OTHER): 4,
             (MODE_OUT, KIND_AUDIO): 5, (MODE_OUT, KIND_MIDI): 6, (MODE_OUT, KIND_CV): 7,
             (MODE_OUT, KIND_PARAM): 8, (MODE_OUT, KIND_OTHER): 9}
    rows.sort(key=lambda row: (order.get((row["old"]["mode"], row["old"]["kind"]), 99),
                               row["old"]["index"], row["old"]["name"].casefold()))
    return rows


def resolve_target(target, new_ports):
    """Turn a dialog target into an actual new port, or None."""
    if not target:
        return None
    new_ports = index_ports(new_ports)
    role_key = target.get("role_key")
    if role_key:
        if role_key == "event":
            # Multiple event ports share the role; use the recorded index.
            index = (target.get("role") or (None, None, 0))[2]
            for new in new_ports:
                if new["kind"] == KIND_MIDI and new["mode"] == target.get("mode", MODE_IN) and new["index"] == index:
                    return new
        for new in new_ports:
            if port_role(new) == role_key:
                return new
        if role_key.startswith("sc:"):
            return None
    if "name" in target:
        mode = target.get("mode", MODE_IN)
        kind = target.get("kind", KIND_OTHER)
        name = target.get("name", "")
        for new in new_ports:
            if new["mode"] == mode and new["kind"] == kind and new["name"].casefold() == name.casefold():
                return new
    role = target.get("role")
    if role:
        mode, kind, index = role
        for new in new_ports:
            if new["mode"] == mode and new["kind"] == kind and new["index"] == index:
                return new
    return None


def is_compatible(old, target):
    if not target:
        return False
    if "role" in target and "name" not in target:
        mode, kind, _index = target["role"]
        return old["mode"] == mode and old["kind"] == kind
    return old["mode"] == target.get("mode") and old["kind"] == target.get("kind")


def validate_rows(rows):
    """Return an error string, or None when the plan can be applied."""
    used_outputs = {}
    for row in rows:
        target = row.get("target")
        if not target:
            continue
        old = row["old"]
        if "name" in target:
            key = ("port", target.get("mode"), target.get("kind"),
                   target.get("name", "").casefold(), target.get("index"))
        else:
            key = ("role", target.get("role_key"), (target.get("role") or (None, None, 0))[2])
        if old["mode"] == MODE_OUT:
            other = used_outputs.get(key)
            if other is not None:
                return "Outputs %r and %r both map to the same port" % (other, old["name"])
            used_outputs[key] = old["name"]
    return None
